INSERT INTO `servicios` (`id`, `clave`, `nombre`, `icono`, `descripcion`, `orden`, `activo`) VALUES (1,'resguardo','Servicio de resguardo y orden','i-resguardo','Ayudarás a cuidar los espacios, orientar a los peregrinos y mantener el orden para que todos podamos vivir este encuentro con tranquilidad.',10,1);
INSERT INTO `servicios` (`id`, `clave`, `nombre`, `icono`, `descripcion`, `orden`, `activo`) VALUES (2,'acogida','Servicio de acogida y hospitalidad','i-acogida','Serás de los primeros rostros que recibirán a quienes lleguen. Orientar, acompañar, escuchar y hacer sentir a todos como en casa.',20,1);
INSERT INTO `servicios` (`id`, `clave`, `nombre`, `icono`, `descripcion`, `orden`, `activo`) VALUES (3,'comunicacion','Servicio de comunicación','i-comunicacion','¡Cuenta lo que estamos viviendo! Apoyarás en fotografía, video, redes sociales, contenidos y difusión de todo lo que ocurra durante la visita.',30,1);
INSERT INTO `servicios` (`id`, `clave`, `nombre`, `icono`, `descripcion`, `orden`, `activo`) VALUES (4,'logistica','Servicio de logística','i-logistica','Detrás de cada gran encuentro hay un gran equipo. Apoyarás en materiales, espacios, distribución, traslados y todo lo necesario para que las cosas funcionen.',40,1);
INSERT INTO `servicios` (`id`, `clave`, `nombre`, `icono`, `descripcion`, `orden`, `activo`) VALUES (5,'auxilios','Servicio de primeros auxilios','i-auxilios','Estarás atento al bienestar de los peregrinos, brindando apoyo y atención básica ante cualquier situación que pueda presentarse.',50,1);
INSERT INTO `servicios` (`id`, `clave`, `nombre`, `icono`, `descripcion`, `orden`, `activo`) VALUES (6,'traduccion','Servicio de traducción e interpretación','i-traduccion','Ayudarás a romper las barreras del idioma para que el mensaje y la experiencia del encuentro puedan llegar a todos.',60,1);
